#!/usr/bin/env node
// Probe: confirm OpenViking-related event shapes in DSH session logs. Read-only.
import fs from 'fs';
import zlib from 'zlib';
import path from 'path';
import os from 'os';

const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return buf.toString('utf8'); } }
  let out = '';
  for (let k = 0; k < idx.length; k++) {
    const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
  }
  return out;
}
function load(fp) {
  const ev = [];
  for (const l of dec(fs.readFileSync(fp)).split('\n')) { if (!l) continue; try { ev.push(JSON.parse(l)); } catch {} }
  return ev;
}
const txt = c => Array.isArray(c) ? c.map(x => x.text || '').join('') : (typeof c === 'string' ? c : '');
const clip = (s, n) => (s || '').replace(/\s+/g, ' ').slice(0, n);

const base = path.join(os.homedir(), '.dsh', 'sessions');
const files = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name)) files.push(fp);
  }
})(base);
files.sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs);
console.log('total_log_files=' + files.length);

// samples: newest, one from ~11-05, one from ~11-02, one old (before 11-02)
const T8 = 8 * 3600 * 1000;
const dayOf = ms => new Date(ms + T8).toISOString().slice(0, 10);
const byDay = {};
for (const f of files) { const d = dayOf(fs.statSync(f).mtimeMs); (byDay[d] ||= []).push(f); }
console.log('days=' + Object.keys(byDay).sort().join(','));
const picks = [files[0]];
for (const d of ['2026-11-05', '2026-11-02', '2026-10-28']) if (byDay[d]) picks.push(byDay[d][0]);

for (const fp of picks) {
  const ev = load(fp);
  const types = {};
  for (const e of ev) types[e.type] = (types[e.type] || 0) + 1;
  const topTypes = Object.entries(types).sort((a, b) => b[1] - a[1]).slice(0, 18);
  const calls = {};
  for (const e of ev) if (e.type === 'tool/call') calls[e.data?.name || '?'] = (calls[e.data?.name || '?'] || 0) + 1;
  const topCalls = Object.entries(calls).sort((a, b) => b[1] - a[1]).slice(0, 15);
  const ovHits = ev.filter(e => /openviking/i.test(JSON.stringify(e).slice(0, 4000)));
  const ctxHits = ev.filter(e => /<openviking-context>/.test(txt(e.data?.message?.content) || txt(e.data?.content) || ''));
  console.log('\n=== ' + dayOf(fs.statSync(fp).mtimeMs) + ' ' + path.basename(path.dirname(fp)).slice(0, 24) + ' events=' + ev.length + ' ===');
  console.log('types: ' + JSON.stringify(topTypes));
  console.log('toolcalls: ' + JSON.stringify(topCalls));
  console.log('ov_events=' + ovHits.length + ' ctx_events=' + ctxHits.length);
  for (const e of ovHits.slice(0, 3)) console.log('  OV[' + e.type + '] ' + clip(JSON.stringify(e), 420));
  for (const e of ctxHits.slice(0, 2)) console.log('  CTX[' + e.type + '] ' + clip(JSON.stringify(e), 420));
  // any plugin/memory event types
  const special = Object.entries(types).filter(([k]) => /memory|recall|inject|plugin|profile|commit|capture|extract/i.test(k));
  console.log('special_types: ' + JSON.stringify(special));
  // timestamps
  const ts = ev.map(e => e.time || e.ts || e.timestamp).filter(Boolean);
  console.log('ts_sample: ' + JSON.stringify(ts.slice(0, 2)) + ' ... ' + JSON.stringify(ts.slice(-2)));
}

#!/usr/bin/env node
/**
 * OpenViking effect audit over DSH session logs (read-only).
 * Counts: profile injection, per-step recall injection, injected volume,
 * MCP tool calls, read-through, empty recalls, errors; by day and by session.
 */
import fs from 'fs';
import zlib from 'zlib';
import path from 'path';
import os from 'os';

const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return buf.toString('utf8'); } }
  let out = '';
  for (let k = 0; k < idx.length; k++) {
    const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
  }
  return out;
}
const txt = c => Array.isArray(c) ? c.map(x => x.text || '').join('') : (typeof c === 'string' ? c : '');
const T8 = 8 * 3600 * 1000;
const dayOf = ms => new Date(ms + T8).toISOString().slice(0, 10);

const base = path.join(os.homedir(), '.dsh', 'sessions');
const files = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name)) files.push(fp);
  }
})(base);

const PER_STEP_MARK = 'Relevant memory from OpenViking';
const PROFILE_MARK = '<openviking-context source="profile">';

function analyze(fp) {
  const r = {
    fp, sid: path.basename(path.dirname(fp)).replace(/^session-/, '').slice(0, 8),
    day: dayOf(fs.statSync(fp).mtimeMs), events: 0, steps: 0, userMsgs: 0,
    profileEvents: 0, profileMaxChars: 0, profileItems: 0,
    recallEvents: 0, recallChars: 0, recallMemTotal: 0, recallEmpty: 0, recallMaxChars: 0,
    ovCalls: {}, vikingPathCalls: 0, ovErrors: 0, errSamples: [],
    firstTs: 0, lastTs: 0
  };
  let s; try { s = dec(fs.readFileSync(fp)); } catch { return r; }
  const lines = s.split('\n');
  for (const l of lines) {
    if (!l) continue;
    const isCall = l.includes('"tool/call"'), isResult = l.includes('"tool/result"');
    const isStep = l.includes('"step/start"'), isUser = l.includes('"user/message"');
    const isInbox = l.includes('"agent/inbox/spliced"');
    const hasOv = l.includes('openviking') || l.includes('OpenViking');
    if (!(isCall || isResult || isStep || isUser || isInbox || hasOv)) continue;
    let e; try { e = JSON.parse(l); } catch { continue; }
    r.events++;
    if (typeof e.time === 'number') { if (!r.firstTs || e.time < r.firstTs) r.firstTs = e.time; if (e.time > r.lastTs) r.lastTs = e.time; }
    if (isStep) r.steps++;
    if (isUser) r.userMsgs++;

    // injected text candidates (user/message + inbox/spliced insertions)
    const texts = [];
    const d = e.data || {};
    const ct = txt(d.message && d.message.content) || txt(d.content);
    if (ct) texts.push(ct);
    if (Array.isArray(d.inserted)) for (const ins of d.inserted) { const t = txt(ins.content); if (t) texts.push(t); }
    for (const t of texts) {
      if (t.includes(PROFILE_MARK)) {
        r.profileEvents++;
        if (t.length > r.profileMaxChars) { r.profileMaxChars = t.length; r.profileItems = (t.match(/^\s+- .+\.md\s*$/gm) || []).length; }
      } else if (t.includes(PER_STEP_MARK)) {
        r.recallEvents++;
        r.recallChars += t.length;
        if (t.length > r.recallMaxChars) r.recallMaxChars = t.length;
        const n = (t.match(/<memory uri=/g) || []).length;
        r.recallMemTotal += n;
        if (n === 0) r.recallEmpty++;
      }
    }

    if (isCall) {
      const nm = d.name || '?';
      if (/openviking/i.test(nm)) r.ovCalls[nm] = (r.ovCalls[nm] || 0) + 1;
      const a = d.arguments || '';
      if (typeof a === 'string' && a.includes('viking://')) r.vikingPathCalls++;
    }
    if (isResult && d.error) {
      const es = JSON.stringify(d.error);
      if (/openviking|1933|ECONNREFUSED|viking:\/\//i.test(es)) {
        r.ovErrors++;
        if (r.errSamples.length < 3) r.errSamples.push(es.slice(0, 160));
      }
    }
  }
  if (r.lastTs) r.day = dayOf(r.lastTs);
  return r;
}

const rows = files.map(analyze);
const ovTool = r => Object.values(r.ovCalls).reduce((a, b) => a + b, 0);
const hasOv = r => r.profileEvents > 0 || r.recallEvents > 0 || ovTool(r) > 0;

// ---- by day ----
const days = {};
for (const r of rows) {
  const k = r.day;
  (days[k] ||= { sessions: 0, ovSessions: 0, profSessions: 0, recallSessions: 0, profileEvents: 0, recallEvents: 0, recallChars: 0, recallMem: 0, recallEmpty: 0, steps: 0, ovCalls: 0, tools: {}, errors: 0 });
  const D = days[k];
  D.sessions++;
  if (hasOv(r)) D.ovSessions++;
  if (r.profileEvents) D.profSessions++;
  if (r.recallEvents) D.recallSessions++;
  D.profileEvents += r.profileEvents; D.recallEvents += r.recallEvents; D.recallChars += r.recallChars;
  D.recallMem += r.recallMemTotal; D.recallEmpty += r.recallEmpty; D.steps += r.steps;
  D.ovCalls += ovTool(r); D.errors += r.ovErrors;
  for (const [k2, v] of Object.entries(r.ovCalls)) D.tools[k2] = (D.tools[k2] || 0) + v;
}
const estTok = c => Math.round(c / 2.2); // mixed CJK/ASCII, rough
console.log('=== A. 按日汇总（OV=OpenViking）===');
console.log('day        sess  ovSess profSess recallSess | profileEv recallEv recallChars estTok recallMem emptyRecall steps ovCalls err');
for (const k of Object.keys(days).sort()) {
  const D = days[k];
  console.log([k, String(D.sessions).padStart(5), String(D.ovSessions).padStart(7), String(D.profSessions).padStart(9), String(D.recallSessions).padStart(11), '|',
    String(D.profileEvents).padStart(9), String(D.recallEvents).padStart(9), String(D.recallChars).padStart(12), String(estTok(D.recallChars)).padStart(7),
    String(D.recallMem).padStart(10), String(D.recallEmpty).padStart(12), String(D.steps).padStart(6), String(D.ovCalls).padStart(8), String(D.errors).padStart(4)].join(' '));
}

// ---- before / after ----
const groups = { 'BEFORE(<=11-01)': r => r.day <= '2026-11-01', 'AFTER(>=11-02)': r => r.day >= '2026-11-02' };
console.log('\n=== B. 开启前后对比 ===');
for (const [g, f] of Object.entries(groups)) {
  const R = rows.filter(f);
  const sum = k => R.reduce((a, r) => a + k(r), 0);
  const sess = R.length, ovS = R.filter(hasOv).length, profS = R.filter(r => r.profileEvents).length, recS = R.filter(r => r.recallEvents).length;
  const rev = sum(r => r.recallEvents), rc = sum(r => r.recallChars), rm = sum(r => r.recallMemTotal), re = sum(r => r.recallEmpty);
  const calls = sum(ovTool), steps = sum(r => r.steps), errs = sum(r => r.ovErrors);
  console.log(`${g}: 会话 ${sess} | 含OV注入 ${ovS} (${(ovS / sess * 100).toFixed(0)}%) | profile注入会话 ${profS} (${(profS / sess * 100).toFixed(0)}%) | 逐步召回会话 ${recS} (${(recS / sess * 100).toFixed(0)}%)`);
  console.log(`   召回注入 ${rev} 次 / ${rc} 字符 ≈ ${estTok(rc)} token | 注入记忆条目 ${rm} | 空召回 ${re} (${rev ? (re / rev * 100).toFixed(1) : 0}%) | 步数 ${steps} | MCP调用 ${calls} | OV错误 ${errs}`);
}

// ---- tool mix (after) ----
console.log('\n=== C. 开启后 MCP 工具调用构成 ===');
