// ---- top sessions by recall volume ----
console.log('\n=== E. 召回注入量 Top12 会话（开启后）===');
A.sort((a, b) => b.recallChars - a.recallChars).slice(0, 12).forEach(r => {
  console.log(`  ${r.sid} ${r.day} steps=${String(r.steps).padStart(4)} recallEv=${String(r.recallEvents).padStart(4)} chars=${String(r.recallChars).padStart(8)} mem=${String(r.recallMemTotal).padStart(4)} empty=${String(r.recallEmpty).padStart(3)} ovCalls=${ovTool(r)} err=${r.ovErrors}`);
});

// ---- errors ----
const errRows = rows.filter(r => r.ovErrors > 0);
console.log('\n=== F. OV 相关工具错误 ===');
console.log('  sessions_with_errors=' + errRows.length + ' total_errors=' + errRows.reduce((a, r) => a + r.ovErrors, 0));
errRows.slice(0, 8).forEach(r => console.log(`  ${r.sid} ${r.day} n=${r.ovErrors} ${r.errSamples.join(' | ').slice(0, 220)}`));

// ---- files processed ----
