#!/usr/bin/env node
/** Token-cost impact of enabling OpenViking, on real (metered) sessions. Read-only. */
import fs from 'fs';
import path from 'path';
import os from 'os';
const T8 = 8 * 3600 * 1000;
const dayOf = ms => new Date(ms + T8).toISOString().slice(0, 10);
const base = path.join(os.homedir(), '.dsh', 'storages', 'session_projcache', 'sessions');
const rows = [];
for (const fn of fs.readdirSync(base).filter(x => x.endsWith('.json'))) {
  let j; try { j = JSON.parse(fs.readFileSync(path.join(base, fn), 'utf8')); } catch { continue; }
  const R = j.record?.rows || {};
  const t = R.tokenUsage?.val?.totals || {};
  const st = R.sessionStats?.val || {};
  const id = j.record?.identity || {};
  const mdl = R.modelSelection?.val?.lastUsed || {};
  const created = id.createdAt || 0;
  rows.push({
    sid: fn.replace(/^session-/, '').slice(0, 8), day: created ? dayOf(created) : '?',
    steps: st.steps || 0, uncached: t.uncachedInputTokens || 0, cacheRead: t.cacheReadTokens || 0,
    cacheWrite: t.cacheWriteTokens || 0, output: t.outputTokens || 0,
    provider: mdl.provider || '?', model: mdl.model || '?'
  });
}
const cost = r => r.cacheRead * 0.1 + r.uncached;
const sum = (rs, k) => rs.reduce((a, r) => a + k(r), 0);
function report(label, rs) {
  const S = sum(rs, r => r.steps), U = sum(rs, r => r.uncached), C = sum(rs, r => r.cacheRead), O = sum(rs, r => r.output);
  const eq = C * 0.1 + U;
  console.log(`${label}: 会话 ${rs.length} | steps ${S} | uncached ${U} | cacheRead ${C} | output ${O} | 等效成本 ${Math.round(eq)}`);
  console.log(`   每步: cacheRead ${S ? (C / S).toFixed(0) : 0} | uncached ${S ? (U / S).toFixed(0) : 0} | 等效成本 ${S ? (eq / S).toFixed(0) : 0} | 命中率 ${(C / Math.max(1, C + U) * 100).toFixed(1)}% | 每会话等效成本 ${rs.length ? Math.round(eq / rs.length) : 0}`);
}
console.log('=== 真实计量会话按日（等效成本 = cacheRead*0.1 + uncached）===');
console.log('day        sess  steps  cacheRead   uncached   等效成本  每步cacheRead 每步等效 命中率');
const days = {};
for (const r of rows) (days[r.day] ||= []).push(r);
for (const d of Object.keys(days).sort()) {
  const rs = days[d].filter(r => r.steps > 0); if (!rs.length) continue;
  const S = sum(rs, r => r.steps), C = sum(rs, r => r.cacheRead), U = sum(rs, r => r.uncached);
  console.log([d, String(rs.length).padStart(5), String(S).padStart(7), String(C).padStart(11), String(U).padStart(11), String(Math.round(C * 0.1 + U)).padStart(11), String(Math.round(C / S)).padStart(13), String(Math.round((C * 0.1 + U) / S)).padStart(9), (C / Math.max(1, C + U) * 100).toFixed(1) + '%'].join(' '));
}
console.log('\n=== 开启前后（仅真实计量会话）===');
report('BEFORE <=11-01', rows.filter(r => r.day <= '2026-11-01' && r.steps > 0));
report('AFTER  >=11-02', rows.filter(r => r.day >= '2026-11-02' && r.steps > 0));
console.log('\n=== 开启后按 provider（排除 steps<10 的短会话）===');
const byP = {};
for (const r of rows.filter(r => r.day >= '2026-11-02' && r.steps >= 10)) (byP[r.provider] ||= []).push(r);
for (const [p, rs] of Object.entries(byP).sort((a, b) => b[1].length - a[1].length)) {
  const S = sum(rs, r => r.steps), C = sum(rs, r => r.cacheRead), U = sum(rs, r => r.uncached);
  console.log(`  ${p.padEnd(22)} sess=${String(rs.length).padStart(3)} steps=${String(S).padStart(6)} 每步cacheRead=${String(Math.round(C / S)).padStart(6)} 每步等效=${String(Math.round((C * 0.1 + U) / S)).padStart(5)} 命中率=${(C / Math.max(1, C + U) * 100).toFixed(1)}%`);
}
console.log('\ntotal_metered_sessions=' + rows.length);

#!/usr/bin/env node
/** Verify recall-injection cadence in one long session. Read-only. */
import fs from 'fs';
import zlib from 'zlib';
import path from 'path';
import os from 'os';
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = []; for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return buf.toString('utf8'); } }
  let out = ''; for (let k = 0; k < idx.length; k++) { const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length; try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {} } return out;
}
const txt = c => Array.isArray(c) ? c.map(x => x.text || '').join('') : (typeof c === 'string' ? c : '');
const base = path.join(os.homedir(), '.dsh', 'sessions');
const target = process.argv[2] || '0f28a5ed';
let fp = null;
(function walk(p) { for (const e of fs.readdirSync(p, { withFileTypes: true })) { const q = path.join(p, e.name); if (e.isDirectory()) walk(q); else if (/\.jsonl\.zstd$/.test(e.name) && path.basename(path.dirname(q)).includes(target)) fp = q; } })(base);
if (!fp) { console.log('not found: ' + target); process.exit(0); }
const ev = [];
for (const l of dec(fs.readFileSync(fp)).split('\n')) { if (!l) continue; try { ev.push(JSON.parse(l)); } catch {} }
const steps = ev.filter(e => e.type === 'step/start').map(e => e.seq);
const turns = ev.filter(e => e.type === 'turn/start').map(e => e.seq);
const users = ev.filter(e => e.type === 'user/message').map(e => e.seq);
const recalls = [], profiles = [];
for (const e of ev) {
  const d = e.data || {};
  const t = txt(d.message && d.message.content) || txt(d.content);
  const texts = [t]; if (Array.isArray(d.inserted)) for (const i of d.inserted) texts.push(txt(i.content));
  for (const x of texts) {
    if (!x) continue;
    if (x.includes('Relevant memory from OpenViking')) recalls.push({ seq: e.seq, type: e.type, chars: x.length, mem: (x.match(/<memory uri=/g) || []).length });
    else if (x.includes('<openviking-context source="profile">')) profiles.push({ seq: e.seq, type: e.type, chars: x.length });
  }
}
const stepIdx = seq => { let n = 0; for (const s of steps) if (s <= seq) n++; return n; };
console.log(`session=${target} events=${ev.length} steps=${steps.length} turns=${turns.length} userMsgs=${users.length}`);
console.log(`profile_injections=${profiles.length} recall_injections=${recalls.length}`);
console.log('profile:', JSON.stringify(profiles));
console.log('turn/start seqs:', JSON.stringify(turns.slice(0, 20)));
console.log('user/message seqs:', JSON.stringify(users.slice(0, 20)));
console.log('\nrecall injections (seq / step# / type / chars / mem):');
recalls.forEach((r, i) => console.log(`  ${String(i + 1).padStart(2)} seq=${String(r.seq).padStart(5)} step#=${String(stepIdx(r.seq)).padStart(4)} ${r.type.padEnd(22)} chars=${String(r.chars).padStart(6)} mem=${r.mem}`));
if (recalls.length > 1) { const gaps = []; for (let i = 1; i < recalls.length; i++) gaps.push(stepIdx(recalls[i].seq) - stepIdx(recalls[i - 1].seq)); console.log('gaps_in_steps=' + JSON.stringify(gaps)); }

