#!/usr/bin/env node
/** Stratified cost analysis: isolate OpenViking injection cost from session length. Read-only. */
import fs from 'fs';
import path from 'path';
import os from 'os';
const T8 = 8 * 3600 * 1000;
const dayOf = ms => new Date(ms + T8).toISOString().slice(0, 10);
const base = path.join(os.homedir(), '.dsh', 'storages', 'session_projcache', 'sessions');
const costRows = [];
for (const fn of fs.readdirSync(base).filter(x => x.endsWith('.json'))) {
  let j; try { j = JSON.parse(fs.readFileSync(path.join(base, fn), 'utf8')); } catch { continue; }
  const R = j.record?.rows || {}, t = R.tokenUsage?.val?.totals || {}, st = R.sessionStats?.val || {};
  costRows.push({
    sid: fn.replace(/^session-/, '').slice(0, 8), day: dayOf(j.record?.identity?.createdAt || 0),
    steps: st.steps || 0, uncached: t.uncachedInputTokens || 0, cacheRead: t.cacheReadTokens || 0
  });
}
const audit = JSON.parse(fs.readFileSync('ov-audit/audit.json', 'utf8'));
const auditBy = {}; for (const a of audit) auditBy[a.sid] = a;
for (const c of costRows) {
  const a = auditBy[c.sid] || {};
  c.profileChars = a.profileMaxChars || 0; c.recallChars = a.recallChars || 0;
  c.recallEvents = a.recallEvents || 0; c.injectChars = c.profileChars + c.recallChars;
  c.after = c.day >= '2026-11-02';
}
const eq = r => r.cacheRead * 0.1 + r.uncached;
const sum = (rs, k) => rs.reduce((a, r) => a + k(r), 0);
const bucket = s => s <= 10 ? '01-10' : s <= 30 ? '11-30' : s <= 60 ? '31-60' : s <= 120 ? '61-120' : s <= 300 ? '121-300' : '300+';

console.log('=== H. 分层对比（按会话步数分桶，剥离会话长度混淆）===');
console.log('bucket    | BEFORE sess/steps/每步cacheRead/每步等效 | AFTER sess/steps/每步cacheRead/每步等效 | Δ每步cacheRead');
for (const b of ['01-10', '11-30', '31-60', '61-120', '121-300', '300+']) {
  const B = costRows.filter(r => !r.after && r.steps > 0 && bucket(r.steps) === b);
  const A = costRows.filter(r => r.after && r.steps > 0 && bucket(r.steps) === b);
  const f = rs => { const S = sum(rs, r => r.steps), C = sum(rs, r => r.cacheRead); return rs.length ? `${String(rs.length).padStart(4)}/${String(S).padStart(6)}/${String(Math.round(C / S)).padStart(6)}/${String(Math.round(sum(rs, eq) / S)).padStart(5)}` : '   -/     -/     -/    -'; };
  const dB = B.length ? sum(B, r => r.cacheRead) / sum(B, r => r.steps) : 0;
  const dA = A.length ? sum(A, r => r.cacheRead) / sum(A, r => r.steps) : 0;
  console.log(`${b.padEnd(9)} | ${f(B)} | ${f(A)} | ${dB && dA ? ((dA / dB - 1) * 100).toFixed(1) + '%' : 'n/a'}`);
}

console.log('\n=== I. 开启后：注入量 vs 每步缓存读（同桶内比较）===');
console.log('bucket    injectLevel        sess  平均steps  每步cacheRead  每步等效  平均注入字符');
for (const b of ['11-30', '31-60', '61-120', '121-300', '300+']) {
  const A = costRows.filter(r => r.after && r.steps > 0 && bucket(r.steps) === b);
  const levels = [['无注入', r => r.injectChars === 0], ['低(<20k)', r => r.injectChars > 0 && r.injectChars < 20000], ['高(>=20k)', r => r.injectChars >= 20000]];
  for (const [nm, f] of levels) {
    const rs = A.filter(f); if (!rs.length) continue;
    const S = sum(rs, r => r.steps), C = sum(rs, r => r.cacheRead);
    console.log(`${b.padEnd(9)} ${nm.padEnd(17)} ${String(rs.length).padStart(4)} ${String(Math.round(S / rs.length)).padStart(10)} ${String(Math.round(C / S)).padStart(13)} ${String(Math.round(sum(rs, eq) / S)).padStart(9)} ${String(Math.round(sum(rs, r => r.injectChars) / rs.length)).padStart(13)}`);
  }
}

console.log('\n=== J. 注入块体量分布（开启后，有注入的会话）===');
const inj = costRows.filter(r => r.after && r.injectChars > 0 && r.steps > 0);
const sorted = inj.map(r => r.injectChars).sort((a, b) => a - b);
const q = p => sorted[Math.floor(sorted.length * p)] || 0;
console.log(`  sessions=${inj.length} min=${sorted[0]} p25=${q(.25)} p50=${q(.5)} p75=${q(.75)} p90=${q(.9)} max=${sorted[sorted.length - 1]}`);
console.log(`  profile 累计 ${sum(inj, r => r.profileChars)} 字符 | 逐步召回累计 ${sum(inj, r => r.recallChars)} 字符 | 合计 ${sum(inj, r => r.injectChars)} 字符`);
const totalSteps = sum(inj, r => r.steps);
console.log(`  这些会话总步数 ${totalSteps} → 若注入块随历史每步重发，粗估额外缓存读 ≈ ${Math.round(sum(inj, r => r.injectChars * r.steps) / 2.2)} token（上界，未扣 compaction）`);

#!/usr/bin/env node
/** Quality of what OpenViking actually injected into post-enablement sessions. Read-only. */
import fs from 'fs';
import zlib from 'zlib';
import path from 'path';
import os from 'os';
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = []; for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return buf.toString('utf8'); } }
  let out = ''; for (let k = 0; k < idx.length; k++) { const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length; try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {} } return out;
}
const txt = c => Array.isArray(c) ? c.map(x => x.text || '').join('') : (typeof c === 'string' ? c : '');
const T8 = 8 * 3600 * 1000;
const dayOf = ms => new Date(ms + T8).toISOString().slice(0, 10);
const base = path.join(os.homedir(), '.dsh', 'sessions');
const files = [];
(function walk(p) { for (const e of fs.readdirSync(p, { withFileTypes: true })) { const fp = path.join(p, e.name); if (e.isDirectory()) walk(fp); else if (/\.jsonl\.zstd$/.test(e.name)) files.push(fp); } })(base);

const all = [], bySession = {}, byDayScores = {};
for (const fp of files) {
  const day = dayOf(fs.statSync(fp).mtimeMs);
  if (day < '2026-11-02') continue;
  const sid = path.basename(path.dirname(fp)).replace(/^session-/, '').slice(0, 8);
  let s; try { s = dec(fs.readFileSync(fp)); } catch { continue; }
  for (const l of s.split('\n')) {
    if (!l || !l.includes('Relevant memory from OpenViking')) continue;
    let e; try { e = JSON.parse(l); } catch { continue; }
    const d = e.data || {};
    const texts = [txt(d.message && d.message.content) || txt(d.content)];
    if (Array.isArray(d.inserted)) for (const i of d.inserted) texts.push(txt(i.content));
    for (const t of texts) {
      if (!t || !t.includes('Relevant memory from OpenViking')) continue;
      const re = /<memory uri="([^"]+)"\s+type="([^"]+)"\s+score="([^"]+)"\s+detail="([^"]+)"\s*>/g;
      let m;
      while ((m = re.exec(t))) {
        const uri = m[1], type = m[2], score = parseFloat(m[3]), detail = m[4];
        all.push({ uri, type, score, detail, sid, day });
        (bySession[sid] ||= []).push(uri);
        (byDayScores[day] ||= []).push(score);
      }
    }
  }
}
const pct = (a, p) => { const s = a.slice().sort((x, y) => x - y); return s[Math.floor(s.length * p)] || 0; };
const scores = all.map(x => x.score);
const uniq = new Set(all.map(x => x.uri));
let dupInSession = 0;
for (const [sid, uris] of Object.entries(bySession)) { const c = {}; for (const u of uris) c[u] = (c[u] || 0) + 1; for (const u in c) if (c[u] > 1) dupInSession += c[u] - 1; }
